package org.springframework.samples.petclinic.owner;

import java.util.List;

import org.springframework.data.jpa.repository.JpaRepository;

/**
 * Repository class for <code>WeightRecord</code> domain objects.
 *
 * @author Spring PetClinic
 */
public interface WeightRecordRepository extends JpaRepository<WeightRecord, Long> {

	/**
	 * Retrieve {@link WeightRecord}s for a specific pet, ordered by date descending
	 * (newest first).
	 * @param petId the pet ID to search for
	 * @return a List of matching {@link WeightRecord}s (or an empty List if none found)
	 */
	List<WeightRecord> findByPetIdOrderByRecordDateDesc(Long petId);

}

